SELECT "account_id" FROM (
  SELECT "account_id", "date", ROW_NUMBER() OVER (ORDER BY "date" ASC) AS "rn"
  FROM "bird_financial_trans"
  WHERE SUBSTRING("date", 1, 4) = '1995'
) WHERE "rn" = 1;

SELECT "name" FROM (
  SELECT "name", "convertedmanacost", ROW_NUMBER() OVER (ORDER BY "convertedmanacost" DESC) AS rn
  FROM "bird_card_games_cards"
  WHERE CAST("frameversion" AS BIGINT) = 2003
) WHERE rn <= 3 ORDER BY rn;
